begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id) values('f5000000-0000-4000-8000-000000000001'),('f5000000-0000-4000-8000-000000000002');
insert into profiles(id,display_name,consented_at) select id,'Outing fixture',now() from auth.users where id::text like 'f5000000-%';
insert into families(id,name) values('f6000000-0000-4000-8000-000000000001','Outing fixture');
insert into family_members(family_id,user_id,role) values('f6000000-0000-4000-8000-000000000001','f5000000-0000-4000-8000-000000000001','owner');
insert into children(id,family_id,name,sex,birth_date) values('f7000000-0000-4000-8000-000000000001','f6000000-0000-4000-8000-000000000001','Outing baby','female',current_date);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f5000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select save_child_record('f8000000-0000-4000-8000-000000000001','f7000000-0000-4000-8000-000000000001','activity',jsonb_build_object('kind','outing','occurred_at',now()-interval '80 minutes','timer_started',true,'timezone','UTC'))$$,'outing starts');
select ok((select timer_started and ended_at is null from child_records where id='f8000000-0000-4000-8000-000000000001'),'outing survives reload as an active timer');
select throws_ok($$select save_child_record(gen_random_uuid(),'f7000000-0000-4000-8000-000000000001','activity',jsonb_build_object('kind','outing','occurred_at',now(),'timer_started',true,'timezone','UTC'))$$,'23505',null,'second active outing is rejected');
select throws_ok($$select save_child_record(gen_random_uuid(),'f7000000-0000-4000-8000-000000000001','activity',jsonb_build_object('kind','outing','occurred_at',now(),'timezone','UTC'))$$,'23514',null,'outing cannot bypass timer state');
select throws_ok($$select save_child_record('f8000000-0000-4000-8000-000000000001','f7000000-0000-4000-8000-000000000001','activity',jsonb_build_object('kind','outing','occurred_at',now()-interval '80 minutes','ended_at',now(),'timer_started',true,'timezone','UTC'),9)$$,'P0001','conflict','stale outing stop is rejected');
select lives_ok($$select save_child_record('f8000000-0000-4000-8000-000000000001','f7000000-0000-4000-8000-000000000001','activity',jsonb_build_object('kind','outing','occurred_at',now()-interval '80 minutes','ended_at',now(),'timer_started',true,'timezone','UTC'),1)$$,'outing stops');
select is((select extract(epoch from ended_at-occurred_at)::integer from child_records where id='f8000000-0000-4000-8000-000000000001'),4800,'outing duration remains in timestamps');
select lives_ok($$select save_child_record(gen_random_uuid(),'f7000000-0000-4000-8000-000000000001','activity',jsonb_build_object('kind','outing','occurred_at',now(),'timer_started',true,'timezone','UTC'))$$,'another outing can start after the previous one ends');
select set_config('request.jwt.claims','{"sub":"f5000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select save_child_record(gen_random_uuid(),'f7000000-0000-4000-8000-000000000001','activity',jsonb_build_object('kind','outing','occurred_at',now(),'timer_started',true,'timezone','UTC'))$$,'42501','forbidden','other families cannot start this child outing');
select * from finish();
rollback;
